{"output": "import { ideas } from "../data/ideas";

export const metadata = {
  title: "灵感漏斗 · AI 学习站",
  description: "老大和斗篷共创的灵感库：从模糊想法到可落地产品的完整漏斗。",
};

const STATUS_ORDER = ["灵感", "收集中", "已整理", "已产出"];

const STATUS_STYLE: Record<string, string> = {
  灵感: "tag-gray",
  收集中: "tag-blue",
  已整理: "tag-accent",
  已产出: "tag-green",
};

export default function IdeasPage() {
  const counts = STATUS_ORDER.map((s) => ({
    status: s,
    count: ideas.filter((i) => i.status === s).length,
  }));

  return (
    <div>
      <div className="page-overline">灵感漏斗</div>
      <h1 className="page-title">💡 灵感漏斗</h1>
      <p className="page-desc">
        一个想法从「灵光一闪」到「能卖的东西」，要经过四道漏斗：
        灵感 → 收集中 → 已整理 → 已产出。这里记的是过程，不是成果。
      </p>

      {/* 漏斗统计 */}
      <div className="space-y-3" style={{ marginBottom: 24 }}>
        <div style={{ display: "flex", gap: 12, flexWrap: "wrap" }}>
          {counts.map((c) => (
            <div
              key={c.status}
              className="card"
              style={{ flex: "1 1 140px", textAlign: "center", padding: "16px 12px" }}
            >", "exit_code": 0, "error": null}

